blocks.text:
paths:
  /posts/{id}:
    get:
      summary: 글 하나 가져오기
      parameters:
        - { name: id, in: path, required: true, schema: { type: integer } }
      responses:
        '200': { content: { application/json: { schema: { $ref: '#/Post' } } } }
        '404': { description: 없음 }
# 이 정의에서 -> 문서 · 타입 · 검증이 자동 생성

// 검증 스키마를 정의하면 문서가 따라온다 (zod + OpenAPI 생성 등)
const Post = z.object({
  id: z.number().int(),
  title: z.string().max(200),
  createdAt: z.string().datetime(),
});
// 이 Post 로: ① 런타임 검증 ② OpenAPI 생성 ③ TS 타입 추론
// 검증에 쓰는 그 정의가 곧 문서의 원본 -> 어긋날 수 없다
